import { MakeLogicType, connect, kea, path, selectors } from 'kea'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'

import { AUDIENCE_TOPIC_WORDS, MESSAGE_CATEGORY_WORDS, TopicVocabulary } from './topicVocabulary'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface topicVocabularyLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    speaksAudience: boolean
    words: TopicVocabulary
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface topicVocabularyLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        speaksAudience: (featureFlags: FeatureFlagsSet) => boolean
        words: (speaksAudience: boolean) => TopicVocabulary
    }
}

export type topicVocabularyLogicType = MakeLogicType<
    topicVocabularyLogicValues,
    {},
    Record<string, any>,
    topicVocabularyLogicMeta
>

export const topicVocabularyLogic = kea<topicVocabularyLogicType>([
    path(['products', 'workflows', 'frontend', 'OptOuts', 'topicVocabularyLogic']),
    connect(() => ({
        values: [featureFlagLogic, ['featureFlags']],
    })),
    selectors({
        speaksAudience: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean => !!featureFlags[FEATURE_FLAGS.WORKFLOWS_AUDIENCE],
        ],
        words: [
            (s) => [s.speaksAudience],
            (speaksAudience: boolean): TopicVocabulary =>
                speaksAudience ? AUDIENCE_TOPIC_WORDS : MESSAGE_CATEGORY_WORDS,
        ],
    }),
])
